const promQuery = `
label_replace(100 * (1 - node_memory_MemAvailable_bytes / node_memory_MemTotal_bytes), "metric", "memory_pct", "", "")
or label_replace(node_load1, "metric", "load1", "", "")
or label_replace(count(node_cpu_seconds_total{mode="idle"}), "metric", "cpu_count", "", "")
or label_replace(100 * (1 - node_filesystem_avail_bytes{mountpoint=~"^(/|/raid5pool)$"} / node_filesystem_size_bytes{mountpoint=~"^(/|/raid5pool)$"}), "metric", "disk_pct", "", "")
or label_replace(sum(node_systemd_unit_state{state="failed"}), "metric", "failed_units", "", "")
or label_replace(zfs_pool_health, "metric", "zfs_health", "", "")
or label_replace(smartctl_device_smart_status, "metric", "smart_status", "", "")
`;

const prom = await this.helpers.httpRequest({
  method: 'GET',
  url: 'http://127.0.0.1:8451/api/v1/query',
  qs: { query: promQuery },
  json: true,
});

const series = prom?.data?.result ?? [];
const byMetric = (name) => series.filter((s) => s.metric.metric === name);
const value = (s) => Number(s.value[1]);

const memoryPct = value(byMetric('memory_pct')[0]);
const load1 = value(byMetric('load1')[0]);
const cpuCount = value(byMetric('cpu_count')[0]);
const failedUnits = value(byMetric('failed_units')[0]);

const disks = byMetric('disk_pct').map((s) => ({ mountpoint: s.metric.mountpoint, pct: value(s) }));
const zfsPools = byMetric('zfs_health').map((s) => ({ pool: s.metric.pool, healthy: value(s) === 0 }));
const smartDevices = byMetric('smart_status').map((s) => ({ device: s.metric.device, healthy: value(s) === 1 }));

// Gatus already alerts on failure by itself -- this section only adds a status
// summary to the digest, so a Gatus outage degrades the email, not the run.
let gatus = [];
try {
  gatus = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://127.0.0.1:8494/api/v1/endpoints/statuses',
    json: true,
  });
} catch (error) {
  gatus = [];
}

const services = gatus.map((endpoint) => {
  const last = endpoint.results?.[endpoint.results.length - 1];
  return { name: endpoint.name, up: last?.success ?? false };
});

const loadRatio = cpuCount ? load1 / cpuCount : 0;
const status = (v, warn, critical) => (v >= critical ? 'critical' : v >= warn ? 'warn' : 'ok');

const rows = [
  {
    label: 'cpu_load',
    value: `${load1.toFixed(2)}`,
    detail: `${(loadRatio * 100).toFixed(0)}% of ${cpuCount} cores`,
    level: status(loadRatio, 0.7, 1.0),
  },
  { label: 'memory', value: `${memoryPct.toFixed(1)}%`, detail: '', level: status(memoryPct, 80, 90) },
  ...disks.map((d) => ({
    label: `disk ${d.mountpoint}`,
    value: `${d.pct.toFixed(1)}%`,
    detail: '',
    level: status(d.pct, 80, 90),
  })),
  {
    label: 'failed_units',
    value: String(failedUnits),
    detail: '',
    level: failedUnits > 0 ? 'critical' : 'ok',
  },
  ...zfsPools.map((p) => ({
    label: `zpool ${p.pool}`,
    value: p.healthy ? 'ONLINE' : 'NOT ONLINE',
    detail: '',
    level: p.healthy ? 'ok' : 'critical',
  })),
  ...smartDevices.map((d) => ({
    label: `smart ${d.device}`,
    value: d.healthy ? 'PASSED' : 'FAILED',
    detail: '',
    level: d.healthy ? 'ok' : 'critical',
  })),
];

const overall = rows.some((r) => r.level === 'critical') ? 'critical' : rows.some((r) => r.level === 'warn') ? 'warn' : 'ok';

// {{{ Terminal-styled design tokens (shared with the webuntis-radicale digest)
const palette = {
  bg: '#eef1f5',
  card: '#0b0f14',
  cardBorder: '#1c2530',
  divider: '#182029',
  text: '#d6e0ea',
  muted: '#5b7284',
  comment: '#4a7a6b',
  ok: '#3ddc84',
  warn: '#ffb454',
  critical: '#ff5c7a',
};
const tag = { ok: '[ OK ]', warn: '[WARN]', critical: '[CRIT]' };
const overallCopy = {
  ok: 'ALL SYSTEMS NOMINAL',
  warn: 'ATTENTION REQUIRED',
  critical: 'ACTION REQUIRED',
}[overall];
const mono = "ui-monospace,'JetBrains Mono','SFMono-Regular',Menlo,Consolas,'Liberation Mono',monospace";
// }}}

const rowsHtml = rows
  .map((r) => {
    const c = palette[r.level];
    return `<tr>
      <td style="padding:9px 28px;border-bottom:1px solid ${palette.divider};font-family:${mono};font-size:13px;color:${palette.muted};white-space:nowrap;">${r.label}</td>
      <td style="padding:9px 4px;border-bottom:1px solid ${palette.divider};font-family:${mono};font-size:13px;color:${palette.cardBorder};width:100%;">${'·'.repeat(40)}</td>
      <td style="padding:9px 28px;border-bottom:1px solid ${palette.divider};font-family:${mono};font-size:13px;text-align:right;white-space:nowrap;">
        <span style="color:${palette.text};">${r.value}</span>${r.detail ? `<span style="color:${palette.muted};"> (${r.detail})</span>` : ''}
        <span style="color:${c};font-weight:700;margin-left:10px;">${tag[r.level]}</span>
      </td>
    </tr>`;
  })
  .join('\n');

const servicesHtml = services.length
  ? services
      .map((s) => {
        const c = s.up ? palette.ok : palette.critical;
        return `<tr>
          <td style="padding:7px 28px;font-family:${mono};font-size:13px;color:${palette.muted};white-space:nowrap;">${s.name}</td>
          <td style="padding:7px 4px;font-family:${mono};font-size:13px;color:${palette.cardBorder};width:100%;">${'·'.repeat(40)}</td>
          <td style="padding:7px 28px;font-family:${mono};font-size:13px;text-align:right;white-space:nowrap;">
            <span style="color:${c};font-weight:700;">${s.up ? '[ UP ]' : '[DOWN]'}</span>
          </td>
        </tr>`;
      })
      .join('\n')
  : `<tr><td colspan="3" style="padding:7px 28px;font-family:${mono};font-size:13px;color:${palette.muted};">gatus returned no data.</td></tr>`;

const timestamp = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'medium', timeStyle: 'short' });
const oc = palette[overall];

const html = `<!DOCTYPE html>
<html>
  <body style="margin:0;padding:32px 16px;background:${palette.bg};font-family:${mono};">
    <table role="presentation" width="100%" style="max-width:600px;margin:0 auto;">
      <tr>
        <td style="background:${palette.card};border:1px solid ${palette.cardBorder};border-radius:6px;overflow:hidden;">
          <table role="presentation" width="100%" style="border-collapse:collapse;">
            <tr><td style="height:4px;line-height:4px;font-size:0;background:${oc};">&nbsp;</td></tr>
            <tr>
              <td style="padding:28px 28px 20px 28px;">
                <div style="font-family:${mono};font-size:12px;color:${palette.comment};">$ ssh inari &amp;&amp; health-check --daily</div>
                <div style="font-family:${mono};font-size:21px;font-weight:700;letter-spacing:0.04em;color:${palette.text};margin-top:14px;">HEALTH_MONITOR</div>
                <div style="font-family:${mono};font-size:14px;font-weight:700;color:${oc};margin-top:8px;">${tag[overall]} ${overallCopy}</div>
                <div style="font-family:${mono};font-size:12px;color:${palette.muted};margin-top:10px;">${timestamp} · inari</div>
              </td>
            </tr>
            <tr><td style="border-top:1px solid ${palette.cardBorder};"></td></tr>
            <tr>
              <td style="padding:16px 28px 2px 28px;font-family:${mono};font-size:12px;color:${palette.comment};"># system metrics</td>
            </tr>
            <tr>
              <td style="padding:0 0 8px 0;">
                <table role="presentation" width="100%" style="border-collapse:collapse;">${rowsHtml}</table>
              </td>
            </tr>
            <tr>
              <td style="padding:18px 28px 2px 28px;font-family:${mono};font-size:12px;color:${palette.comment};"># service status (gatus)</td>
            </tr>
            <tr>
              <td style="padding:0 0 20px 0;">
                <table role="presentation" width="100%" style="border-collapse:collapse;">${servicesHtml}</table>
              </td>
            </tr>
            <tr><td style="border-top:1px solid ${palette.cardBorder};"></td></tr>
            <tr>
              <td style="padding:16px 28px;font-family:${mono};font-size:11px;color:${palette.muted};">generated by n8n @ inari</td>
            </tr>
          </table>
        </td>
      </tr>
    </table>
  </body>
</html>`;

return [{ json: { subject: `[inari] ${tag[overall]} ${overallCopy}`, html } }];
